"""Foreground native Ollama tool loop with bounded rounds and visible evidence."""
import json
import time
import urllib.error
import urllib.request
from context_budget import estimate_context, ensure_generation_room
from assistant_tools import SCHEMAS, execute, evidence, answer_with_evidence, request_scope, schemas_for, requests_check
from profile_policy import resolve_profile
from storage import settings

def native_turn(engine, messages, schemas, profile, limit, temperature, thinking, abort, deadline, foreground=True):
    from engine import BackendError, Cancelled
    payload={'model':profile.model_id,'messages':messages,'tools':schemas,'stream':True,
             'think':thinking,'options':{'num_ctx':profile.context_tokens,'num_predict':limit,
             'temperature':temperature,'top_p':profile.top_p,'top_k':profile.top_k,
             'presence_penalty':profile.presence_penalty}}
    request=urllib.request.Request(settings()['ollama_url'].rstrip('/')+'/api/chat',
            data=json.dumps(payload).encode(),headers={'Content-Type':'application/json'})
    message={'role':'assistant','content':'','thinking':'','tool_calls':[]}
    with engine.gate.hold(foreground,abort):
        left=min(profile.generation_timeout_seconds,deadline-time.monotonic())
        if left<=0: raise BackendError('tool_turn_deadline_exceeded')
        try:
            with urllib.request.urlopen(request,timeout=left) as response:
                while True:
                    if engine.stop.is_set() or abort(): raise Cancelled()
                    left=deadline-time.monotonic()
                    if left<=0: raise BackendError('tool_turn_deadline_exceeded')
                    # Bound each blocking read to the remaining whole-request deadline.
                    if getattr(response,'fp',None) is not None and hasattr(response.fp,'raw'):
                        response.fp.raw._sock.settimeout(left)
                    line=response.readline(262145)
                    if not line: raise BackendError('backend_stream_incomplete')
                    if len(line)>262144: raise BackendError('oversized_backend_chunk')
                    try: data=json.loads(line)
                    except ValueError: raise BackendError('invalid_backend_response') from None
                    if data.get('error'): raise BackendError('backend_generation_failed')
                    chunk=data.get('message',{})
                    for key in ('content','thinking'):
                        value=chunk.get(key,'')
                        if not isinstance(value,str): raise BackendError('invalid_backend_message')
                        message[key]+=value
                        if len(message[key].encode())>65536: raise BackendError('oversized_backend_message')
                    calls=chunk.get('tool_calls',[])
                    if not isinstance(calls,list): raise BackendError('invalid_backend_tool_calls')
                    for call in calls:
                        if not isinstance(call,dict) or not isinstance(call.get('function'),dict):
                            raise BackendError('invalid_backend_tool_call')
                        fn=call['function']
                        if not isinstance(fn.get('name'),str) or not isinstance(fn.get('arguments'),dict):
                            raise BackendError('invalid_backend_tool_arguments')
                        clean={'type':'function','function':{'name':fn['name'],'arguments':fn['arguments']}}
                        if clean not in message['tool_calls']: message['tool_calls'].append(clean)
                        if len(message['tool_calls'])>4: raise BackendError('too_many_tool_calls')
                    if data.get('done'):
                        if data.get('done_reason') not in ('stop','length'):
                            raise BackendError('unrecognized_backend_finish')
                        return message,data
        except urllib.error.HTTPError as exc: raise BackendError('backend_http_'+str(exc.code)) from None
        except (urllib.error.URLError,TimeoutError,OSError): raise BackendError('backend_unavailable') from None

def tool_stream(engine,messages,max_tokens,temperature,abort,profile_id,think_override):
    from engine import BackendError, Cancelled
    profile=resolve_profile(profile_id)
    thinking=profile.think if think_override is None else think_override
    temp=profile.temperature if temperature is None else temperature
    history=[dict(m) for m in messages]
    scope=request_scope(messages); trace=[]; seen=set(); prompted=False
    totals={'input_tokens':0,'output_tokens':0,'generation_seconds':0,'context_checks':[]}
    deadline=time.monotonic()+min(profile.generation_timeout_seconds*2,180)
    limit=max_tokens or profile.max_output_tokens
    for round_no in range(4):
        if engine.stop.is_set() or abort(): raise Cancelled()
        schemas=schemas_for(messages) if round_no<3 and len(trace)<4 else []
        try:
            estimate=estimate_context(history,profile.context_tokens,thinking=thinking,tools=schemas,internal_tools=True)
            ensure_generation_room(estimate)
        except ValueError:
            if not trace: raise
            yield {'text':'The checks below completed, but there is not enough context left for a further summary.'+evidence(trace)}
            yield {'done':True,'finish_reason':'length',**totals,'network_tool_results':trace}
            return
        message,done=native_turn(engine,history,schemas,profile,min(limit,estimate.available_generation_tokens),temp,thinking,abort,deadline)
        totals['context_checks'].append({'round':round_no+1,'estimated_prompt_tokens':estimate.prompt_tokens,
            'actual_prompt_tokens':done.get('prompt_eval_count'),'output_limit':min(limit,estimate.available_generation_tokens)})
        totals['input_tokens']+=done.get('prompt_eval_count',0)
        totals['output_tokens']+=done.get('eval_count',0)
        totals['generation_seconds']+=done.get('eval_duration',0)/1e9
        calls=message['tool_calls']
        if not calls and not trace and not prompted and done['done_reason']=='stop' and requests_check(messages):
            # One bounded retry addresses small-model promises without execution.
            # It still requires a native tool call; no prose is parsed as a command.
            reminder='When a live check is requested, use the supplied tool now. A description or promise is not execution. If the tool does not apply, say that no check was performed.'
            if history[0]['role']=='system': history[0]['content']+=' '+reminder
            else: history.insert(0,{'role':'system','content':reminder})
            prompted=True
            continue
        if done['done_reason']=='length' or not calls:
            text=message['content'].strip()
            if not text: text='The model did not return a final summary.'
            if trace: text=answer_with_evidence(text,trace)
            elif requests_check(messages): text+='\n\nNo live tool check was performed in this reply.'
            yield {'text':text}
            finish='stop' if trace and any(r['name'] not in ('network_probe','http_get','ssh_status') for r in trace) else done['done_reason']
            yield {'done':True,'finish_reason':finish,**totals,'network_tool_results':trace}
            return
        if not schemas: raise BackendError('tool_round_limit_exceeded')
        # Keep native thinking for Ollama, and the equivalent key for the pinned HF template.
        message['reasoning_content']=message['thinking']
        history.append(message)
        for call in calls:
            if engine.stop.is_set() or abort(): raise Cancelled()
            if time.monotonic()>deadline: raise BackendError('tool_turn_deadline_exceeded')
            fn=call['function']; key=json.dumps(fn,sort_keys=True)
            if len(trace)>=4 or key in seen:
                result={'ok':False,'tool':fn['name'],'error':'Repeated call or four-call request limit reached.'}
            else:
                seen.add(key)
                result=execute(fn['name'],fn['arguments'],scope)
                trace.append({'name':fn['name'],'arguments':fn['arguments'],'result':result})
            history.append({'role':'tool','tool_name':fn['name'],'content':json.dumps(result,ensure_ascii=False)})
        # A completed single-purpose tool has a factual renderer; a second model summary adds no information.
        if len(scope['names'])==1 and not (scope['names'] & {'network_probe','http_get','ssh_status'}) and trace and all(r['result']['ok'] for r in trace):
            yield {'text':answer_with_evidence('',trace)}
            yield {'done':True,'finish_reason':'stop',**totals,'network_tool_results':trace}
            return
    raise BackendError('tool_round_limit_exceeded')

